<span class="line"><span style="color:#61AFEF;">docker</span><span style="color:#98C379;"> run</span><span style="color:#D19A66;"> -d</span><span style="color:#D19A66;"> --name</span><span style="color:#98C379;"> app2</span><span style="color:#D19A66;"> --network</span><span style="color:#98C379;"> mynet</span><span style="color:#98C379;"> nginx</span></span>
